CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS templates (id BIGINT PRIMARY KEY, title VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, category VARCHAR(40) NOT NULL, cover_url VARCHAR(255) NOT NULL, required_image_count INT NOT NULL, accepted_mime_types VARCHAR(100) NOT NULL, max_file_size_bytes BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets (id CHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, original_filename VARCHAR(255) NOT NULL, mime_type VARCHAR(40) NOT NULL, file_size BIGINT NOT NULL, storage_path VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS creation_tasks (id CHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, template_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, current_stage VARCHAR(30), failed_stage VARCHAR(30), error_message VARCHAR(500), result_url VARCHAR(255), fail_at VARCHAR(30) NOT NULL, stage_delay_ms INT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), started_at TIMESTAMP(3), completed_at TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(template_id) REFERENCES templates(id), INDEX idx_user_created(user_id, created_at), INDEX idx_status(status));
CREATE TABLE IF NOT EXISTS task_assets (task_id CHAR(36) NOT NULL, asset_id CHAR(36) NOT NULL, position INT NOT NULL, PRIMARY KEY(task_id, asset_id), FOREIGN KEY(task_id) REFERENCES creation_tasks(id), FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS task_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, task_id CHAR(36) NOT NULL, stage VARCHAR(30), event_type VARCHAR(20) NOT NULL, message VARCHAR(500), created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(task_id) REFERENCES creation_tasks(id), INDEX idx_events_task(task_id,id));
CREATE TABLE IF NOT EXISTS demo_accounts (user_id BIGINT PRIMARY KEY, credits INT NOT NULL DEFAULT 5000, plan VARCHAR(16) NOT NULL DEFAULT 'FREE', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
